def cele_cislo(text):
    # int může odmítnout obsah, například písmena.
    try:
        return int(text)
    except ValueError:
        return None


# Neplatný vstup neukončí celý program.
for text in ["12", "ahoj", "", "-3"]:
    print(text, "->", cele_cislo(text))

def podil(a, b):
    try:
        return a / b
    # Zachytíme konkrétní chybu dělení nulou.
    except ZeroDivisionError:
        return None


print(podil(12, 3))
print(podil(12, 0))
# Po zachycené chybě může pokračovat další výpočet.
print(podil(12, 6))
